import React, { useEffect, useRef } from 'react';
import './inputitems.css';

const InputItem = ({ label, placeholder = ' ', name, onChange, type = 'text', isTextArea = false, className, value }) => {
    const textareaRef = useRef(null);

    useEffect(() => {
        if (isTextArea && textareaRef.current) {
            textareaRef.current.style.height = "40px"; // Reset height
            textareaRef.current.style.height = `${textareaRef.current.scrollHeight}px`; // Adjust height dynamically
        }
    }, [value]);

    return (
        <div className={`row ${className}`}> 
            <div className='input'>
                {!isTextArea ? (
                    <input 
                        onChange={onChange} 
                        placeholder={placeholder} 
                        name={name} 
                        type={type} 
                        value={value} 
                    />
                ) : (
                    <textarea 
                        ref={textareaRef}
                        onChange={onChange} 
                        placeholder={placeholder} 
                        name={name}
                        value={value} 
                    ></textarea>
                )}
                <label>{label}</label>
            </div>
        </div>
    );
};

export default InputItem;
